<?php
return function(PDO $pdo): void {$pdo->exec("CREATE TABLE IF NOT EXISTS project_collaborators (id INT AUTO_INCREMENT PRIMARY KEY,project_id VARCHAR(64) NOT NULL,user_id INT NOT NULL,role VARCHAR(50) NOT NULL DEFAULT 'collaborator',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY unique_project_user(project_id,user_id),INDEX idx_pc_project(project_id),INDEX idx_pc_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$pdo->exec("CREATE TABLE IF NOT EXISTS project_collaboration_invites (id VARCHAR(80) PRIMARY KEY,project_id VARCHAR(64) NOT NULL,invited_user_id INT NOT NULL,invited_by_user_id INT NOT NULL,role VARCHAR(50) NOT NULL DEFAULT 'collaborator',status VARCHAR(50) NOT NULL DEFAULT 'pending',responded_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY unique_pending_project_invite(project_id,invited_user_id,status),INDEX idx_pci_project(project_id),INDEX idx_pci_user(invited_user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");};
